+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.grid.GridTester;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import com.vaadin.flow.data.provider.BackEndDataProvider;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.stream.IntStream;
+
+import static ai.unifiedprocess.demo.petclinic.database.tables.VetSpecialties.VET_SPECIALTIES;
+import static ai.unifiedprocess.demo.petclinic.database.tables.Vets.VETS;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    private static final int FIRST_NAME = 0;
+    private static final int LAST_NAME = 1;
+    private static final int SPECIALTIES = 2;
+
+    /** Seeded vets, in the grid's order (last name, then first name). */
+    private static final int SEEDED_VET_COUNT = 6;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002")
+    void veterinariansLinkOpensTheVetDirectory() {
+        navigate(WelcomeView.class);
+
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                        .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected a Veterinarians item in the main menu");
+        UI.getCurrent().navigate(link.getPath());
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        assertDoesNotThrow(() -> find(Grid.class).single(), "Expected the veterinarians grid");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsFirstNameLastNameAndSpecialties() {
+        GridTester<Grid<Object>, Object> grid = openGrid();
+
+        assertEquals("First Name", grid.getHeaderCell(FIRST_NAME));
+        assertEquals("Last Name", grid.getHeaderCell(LAST_NAME));
+        assertEquals("Specialties", grid.getHeaderCell(SPECIALTIES));
+        assertEquals(SEEDED_VET_COUNT, grid.size());
+
+        int ortega = rowOf(grid, "Ortega");
+        assertEquals("Rafael", grid.getCellText(ortega, FIRST_NAME));
+        assertEquals("surgery", grid.getCellText(ortega, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void vetWithoutSpecialtiesShowsNone() {
+        GridTester<Grid<Object>, Object> grid = openGrid();
+
+        assertEquals("none", grid.getCellText(rowOf(grid, "Carter"), SPECIALTIES));
+        assertEquals("none", grid.getCellText(rowOf(grid, "Jenkins"), SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        // Linda Douglas holds surgery (id 2) and dentistry (id 3): id order would be the reverse.
+        GridTester<Grid<Object>, Object> grid = openGrid();
+
+        assertEquals("dentistry, surgery", grid.getCellText(rowOf(grid, "Douglas"), SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridLoadsVetsLazilyFromTheBackend() {
+        int extraVets = 120;
+        IntStream.range(0, extraVets).forEach(i -> dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                .values("Test", "Zz%03d".formatted(i))
+                .execute());
+
+        navigate(VetsView.class);
+        Grid<?> grid = find(Grid.class).single();
+        assertInstanceOf(BackEndDataProvider.class, grid.getDataProvider(),
+                "Expected rows to be fetched from the backend on demand");
+        assertFalse(grid.getDataProvider().isInMemory(), "Expected no in-memory item list");
+
+        GridTester<Grid<Object>, Object> tester = test(find(Grid.class).single());
+        int total = SEEDED_VET_COUNT + extraVets;
+        assertEquals(total, tester.size());
+        assertEquals("Zz119", tester.getCellText(total - 1, LAST_NAME),
+                "Expected the last row to be reachable by scrolling");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVetsRendersAnEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        GridTester<Grid<Object>, Object> grid = openGrid();
+
+        assertEquals(0, grid.size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void vetDirectoryIsReachableWithoutAuthentication() {
+        // No login is performed before navigating.
+        assertDoesNotThrow(() -> navigate(VetsView.class),
+                "Expected /vets to open without authentication");
+        assertDoesNotThrow(() -> find(SideNavItem.class)
+                        .withPropertyValue(SideNavItem::getLabel, "Home").single(),
+                "Expected the view to render inside " + MainLayout.class.getSimpleName());
+    }
+
+    @SuppressWarnings("unchecked")
+    private GridTester<Grid<Object>, Object> openGrid() {
+        navigate(VetsView.class);
+        return test((Grid<Object>) find(Grid.class).single());
+    }
+
+    private static int rowOf(GridTester<Grid<Object>, Object> grid, String lastName) {
+        return IntStream.range(0, grid.size())
+                .filter(row -> lastName.equals(grid.getCellText(row, LAST_NAME)))
+                .findFirst()
+                .orElseThrow(() -> new AssertionError("No row for vet " + lastName));
+    }
+}
